 let path=root.join(format!(".scratch/decomp-progress/{id}.toml"));fs::write(&path,toml::to_string_pretty(&v)?)?;
 let result=Command::new(root.join("target/debug/sm-pipeline")).args(["progress","update","--root"]).arg(root).arg("--update").arg(&path).output()?;
 fs::write(path.with_extension("stdout"),&result.stdout)?;fs::write(path.with_extension("stderr"),&result.stderr)?;
 ensure!(result.status.success(),"publication failed {id}: {}",String::from_utf8_lossy(&result.stderr));println!("{id}: {} {stage} definitions ({context})",routines.len());Ok(())
